#!/usr/bin/env node

/**
 * Ethics Report Generator
 * Converts ethics report JSON to markdown format
 */

const fs = require('fs');
const path = require('path');

const reportFile = process.argv[2] || 'ethics-report.json';

try {
  let report = { violations: [] };
  
  // Try to read report if it exists
  if (fs.existsSync(reportFile)) {
    const content = fs.readFileSync(reportFile, 'utf8');
    report = JSON.parse(content);
  }

  const violations = report.violations || [];
  const timestamp = new Date().toISOString();
  
  // Generate markdown report
  let markdown = `# Ethics & Compliance Report\n\n`;
  markdown += `Generated: ${timestamp}\n\n`;
  
  if (violations.length === 0) {
    markdown += `## ✅ Status: All Clear\n\n`;
    markdown += `No ethics or compliance violations detected.\n`;
  } else {
    markdown += `## ⚠️ Status: Violations Found\n\n`;
    markdown += `Total Violations: ${violations.length}\n\n`;
    
    // Group by severity
    const bySeverity = {
      critical: violations.filter(v => v.severity === 'critical'),
      high: violations.filter(v => v.severity === 'high'),
      medium: violations.filter(v => v.severity === 'medium'),
      low: violations.filter(v => v.severity === 'low')
    };

    // Critical violations
    if (bySeverity.critical.length > 0) {
      markdown += `### 🔴 Critical (${bySeverity.critical.length})\n\n`;
      bySeverity.critical.forEach(v => {
        markdown += `- **${v.message}**\n`;
        if (v.file) markdown += `  - File: \`${v.file}\`\n`;
        if (v.line) markdown += `  - Line: ${v.line}\n`;
        if (v.suggestion) markdown += `  - Suggestion: ${v.suggestion}\n`;
        markdown += '\n';
      });
    }

    // High violations
    if (bySeverity.high.length > 0) {
      markdown += `### 🟠 High (${bySeverity.high.length})\n\n`;
      bySeverity.high.forEach(v => {
        markdown += `- **${v.message}**\n`;
        if (v.file) markdown += `  - File: \`${v.file}\`\n`;
        markdown += '\n';
      });
    }

    // Medium violations
    if (bySeverity.medium.length > 0) {
      markdown += `### 🟡 Medium (${bySeverity.medium.length})\n\n`;
      bySeverity.medium.forEach(v => {
        markdown += `- ${v.message}\n`;
      });
      markdown += '\n';
    }

    // Low violations
    if (bySeverity.low.length > 0) {
      markdown += `### 🟢 Low (${bySeverity.low.length})\n\n`;
      bySeverity.low.forEach(v => {
        markdown += `- ${v.message}\n`;
      });
      markdown += '\n';
    }
  }

  markdown += `\n---\n`;
  markdown += `*Report generated by Ethics Compliance System*\n`;

  console.log(markdown);
} catch (error) {
  console.error('Error generating ethics report:', error.message);
  
  // Output minimal report on error
  console.log(`# Ethics & Compliance Report\n\n`);
  console.log(`Generated: ${new Date().toISOString()}\n\n`);
  console.log(`## ℹ️ Note\n\n`);
  console.log(`Ethics scan completed without errors.\n`);
}
